mod audio;
mod bands;
mod console;
mod diag;
// BIO program for the I2S mic, vendored verbatim from sw/i2s/i2s.rs in
// github.com/rowr111/bio-sim at commit 3913e72. Autogenerated -- do not edit.
mod i2s_bio;
mod pins;
mod uart_out;

use audio::{I2sAudio, FRAME_PERIOD_MS};
use diag::{Diag, Stage};
use uart_out::UartOut;

/// Frames averaged per timing measurement, and how far it must drift to be worth
/// reprinting. Steady state stays silent.
const BANDS_TIMING_FRAMES: u32 = 32;
const BANDS_REPORT_DELTA_MS: f32 = 1.0;

fn main() -> ! {
    // Print panics over USB serial.
    std::panic::set_hook(Box::new(|info| {
        Diag::new().line(&format!("PANIC: {}", info));
    }));

    // USB and the heartbeat come up before anything that can block, so a stalled
    // startup still reports the stage it stopped at.
    let d = Diag::new();
    diag::spawn_heartbeat();
    d.line("");
    d.line("=== ear ===");
    diag::stage(&d, Stage::UsbUp);

    let hal = bao1x_hal_service::Hal::new();
    hal.set_preemption(true);
    diag::stage(&d, Stage::HalUp);

    let tt = ticktimer::Ticktimer::new().unwrap();

    d.line(&format!(
        "I2S pins: PB{} = BCLK, PB{} = SD, PB{} = WS",
        pins::MIC_BCLK_BIO_PIN,
        pins::MIC_SD_BIO_PIN,
        pins::MIC_WS_BIO_PIN,
    ));
    diag::stage(&d, Stage::StartingBio);
    let mut mic = I2sAudio::new();
    diag::stage(&d, Stage::BioUp);

    let mut uart_out = UartOut::new();

    d.line(&format!("FIFO0 level {}", mic.fifo_level()));
    console::help(&d);
    console::spawn();
    diag::stage(&d, Stage::PromptReady);

    // Run the 24-band filterbank on each frame and send framed BandFrames to the eye.
    let mut processor = bands::BandProcessor::new();
    let mut timer = BandsTimer::default();
    let mut starved_reported = 0u32;

    loop {
        // The mic is not Send, so diagnostic commands run here rather than on the
        // console thread. Returns immediately when no key has been pressed.
        console::service(&d, &tt, &mut mic);

        let frame = mic.read_frame();

        // The eye cannot tell a starved frame from a quiet room, so say so.
        let starved = mic.starved_frames();
        if starved != starved_reported {
            d.line(&format!(
                "mic starved: {} frames abandoned, the BIO stopped pushing",
                starved
            ));
            starved_reported = starved;
        }

        let started = tt.elapsed_ms();
        let processed = processor.process(&frame);
        let process_ms = tt.elapsed_ms() - started;
        uart_out.send(&processed);
        console::record_bands(processor.band_levels());
        let (dbfs, norm) = processor.level();
        console::record_refs(
            processor.band_range(),
            processor.level_reference(),
            dbfs,
            norm,
        );
        timer.add(&d, process_ms);
    }
}

/// Filterbank cost, averaged over a batch - the ticktimer only resolves ms.
#[derive(Default)]
struct BandsTimer {
    total_ms: u64,
    frames: u32,
    reported: Option<f32>,
}

impl BandsTimer {
    /// Adds one frame's time. After each batch, publishes the average for the console and
    /// prints it if it has moved.
    fn add(&mut self, d: &Diag, ms: u64) {
        self.total_ms += ms;
        self.frames += 1;
        if self.frames < BANDS_TIMING_FRAMES {
            return;
        }
        let per_frame = self.total_ms as f32 / BANDS_TIMING_FRAMES as f32;
        console::record_bands_time((per_frame * 1000.0) as u32);
        if self
            .reported
            .is_none_or(|last| (per_frame - last).abs() > BANDS_REPORT_DELTA_MS)
        {
            d.line(&format!(
                "bands: {:.2} ms to process each {} ms frame",
                per_frame, FRAME_PERIOD_MS
            ));
            self.reported = Some(per_frame);
        }
        self.total_ms = 0;
        self.frames = 0;
    }
}
